#!/usr/bin/env python3
"""Patches the android/ folder generated by `flutter create` for XRay Vpn.

Run from the project root after:
    flutter create --platforms=android --org xyz.xray --project-name vpn .

Every edit is asserted, so a template change in a newer Flutter fails the
build loudly here instead of producing a subtly broken APK.
"""
import glob
import os
import re
import sys

APP_ID = "xyz.xray.vpn"
APP_LABEL = "XRay Vpn"
MIN_SDK = 24

ROOT = os.getcwd()
APP = os.path.join(ROOT, "android", "app")
MAIN = os.path.join(APP, "src", "main")


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w", encoding="utf-8", newline="\n") as f:
        f.write(s)


def die(msg):
    print("PATCH ERROR: " + msg, file=sys.stderr)
    sys.exit(1)


# ----------------------------------------------------------------- manifest
def patch_manifest():
    p = os.path.join(MAIN, "AndroidManifest.xml")
    s = read(p)

    m = re.search(r"<application\b[^>]*>", s)
    if not m:
        die("<application> tag not found in manifest")
    tag = m.group(0)
    if "android:label=" in tag:
        new = re.sub(r'android:label="[^"]*"', 'android:label="%s"' % APP_LABEL, tag, count=1)
    else:
        new = tag[:-1] + ' android:label="%s">' % APP_LABEL
    # Native libs are extracted via Gradle (useLegacyPackaging), not the manifest.
    new = re.sub(r'\s+android:extractNativeLibs="[^"]*"', "", new)
    s = s.replace(tag, new, 1)

    perms = [
        "android.permission.INTERNET",
        "android.permission.ACCESS_NETWORK_STATE",
        "android.permission.CHANGE_NETWORK_STATE",
        "android.permission.FOREGROUND_SERVICE",
        "android.permission.POST_NOTIFICATIONS",
        "android.permission.WAKE_LOCK",
        "android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS",
    ]
    add = "".join(
        '    <uses-permission android:name="%s"/>\n' % x
        for x in perms
        if 'android:name="%s"' % x not in s
    )
    if add:
        s = s.replace("<application", add + "    <application", 1)

    # Android 11+ package visibility for the app picker (launcher apps only,
    # so no QUERY_ALL_PACKAGES is needed).
    intent = (
        "        <intent>\n"
        '            <action android:name="android.intent.action.MAIN"/>\n'
        '            <category android:name="android.intent.category.LAUNCHER"/>\n'
        "        </intent>\n"
    )
    if "android.intent.category.LAUNCHER" in s and "<queries>" in s and intent.strip() in s:
        pass
    elif "<queries>" in s:
        s = s.replace("<queries>", "<queries>\n" + intent, 1)
    else:
        s = s.replace("</manifest>", "    <queries>\n" + intent + "    </queries>\n</manifest>", 1)

    # Referencing the status icon here stops resource shrinking from removing it
    # (the VPN plugin looks it up by name at runtime).
    meta = '        <meta-data android:name="%s.status_icon" android:resource="@mipmap/ic_stat_vpn"/>\n' % APP_ID
    if "ic_stat_vpn" not in s:
        s = s.replace("</application>", meta + "    </application>", 1)

    write(p, s)


# ------------------------------------------------------------------- gradle
def agp_major():
    for name in ("settings.gradle.kts", "settings.gradle"):
        p = os.path.join(ROOT, "android", name)
        if os.path.exists(p):
            m = re.search(r"com\.android\.application[\"']\)?\s+version\s+[\"'](\d+)\.", read(p))
            if m:
                return int(m.group(1))
    return 0


def patch_gradle():
    kts = os.path.join(APP, "build.gradle.kts")
    grv = os.path.join(APP, "build.gradle")
    if os.path.exists(kts):
        p, is_kts = kts, True
    elif os.path.exists(grv):
        p, is_kts = grv, False
    else:
        die("android/app/build.gradle(.kts) not found")
    s = read(p)

    if is_kts:
        s, n = re.subn(r"minSdk\s*=\s*[^\n]+", "minSdk = maxOf(flutter.minSdkVersion, %d)" % MIN_SDK, s, count=1)
    else:
        s, n = re.subn(
            r"minSdkVersion\s+[^\n]+",
            "minSdkVersion Math.max(flutter.minSdkVersion, %d)" % MIN_SDK,
            s,
            count=1,
        )
    if n != 1:
        die("minSdk line not found in " + os.path.basename(p))

    if s.count(APP_ID) < 2:
        die("namespace/applicationId is not %s - check the flutter create flags" % APP_ID)

    if "useLegacyPackaging" not in s:
        s, n = re.subn(
            r"(^\s*android\s*\{[^\n]*\n)",
            r"\1    packaging {\n        jniLibs {\n            useLegacyPackaging = true\n        }\n    }\n",
            s,
            count=1,
            flags=re.M,
        )
        if n != 1:
            die("android { block not found")
    write(p, s)

    gp = os.path.join(ROOT, "android", "gradle.properties")
    g = read(gp) if os.path.exists(gp) else ""
    props = [
        "android.useAndroidX=true",
        "android.bundle.enableUncompressedNativeLibs=false",
    ]
    # AGP 9 turns on built-in Kotlin and the new DSL, which breaks plugins that
    # still apply `kotlin-android` (flutter_v2ray_client, openvpn_flutter).
    # Flutter's own docs describe these two opt-outs. Only added for AGP >= 9.
    if agp_major() >= 9:
        props += ["android.builtInKotlin=false", "android.newDsl=false"]
        print("AGP 9 detected: added Kotlin/DSL opt-out flags")
    for line in props:
        key = line.split("=")[0]
        if key not in g:
            g += ("\n" if g and not g.endswith("\n") else "") + line + "\n"
    write(gp, g)


# ------------------------------------------------------------------ kotlin
KOTLIN = r'''package xyz.xray.vpn

import android.Manifest
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.drawable.Drawable
import android.net.Uri
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.os.PowerManager
import android.provider.Settings
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.dart.DartExecutor
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel
import java.io.ByteArrayOutputStream
import java.util.concurrent.Executors

/**
 * Process-wide Flutter engine. The SSH tunnel runs in Dart, so the engine must
 * outlive the Activity: otherwise pressing Back would leave the VPN service
 * up while the SOCKS/SSH side is gone (traffic black hole).
 */
object EngineHolder {
    var engine: FlutterEngine? = null
}

class MainActivity : FlutterActivity() {
    private val worker = Executors.newSingleThreadExecutor()
    private val ui = Handler(Looper.getMainLooper())

    override fun provideFlutterEngine(context: Context): FlutterEngine? {
        var e = EngineHolder.engine
        if (e == null) {
            e = FlutterEngine(applicationContext)
            e.dartExecutor.executeDartEntrypoint(DartExecutor.DartEntrypoint.createDefault())
            EngineHolder.engine = e
        }
        return e
    }

    override fun shouldDestroyEngineWithHost(): Boolean = false

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "xyz.xray.vpn/system")
            .setMethodCallHandler { call, result -> handle(call, result) }
    }

    private fun handle(call: MethodCall, result: MethodChannel.Result) {
        when (call.method) {
            "listApps" -> worker.execute {
                val out: List<Map<String, String>> = try {
                    val pm = packageManager
                    val intent = Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER)
                    pm.queryIntentActivities(intent, 0)
                        .map { it.activityInfo.packageName to it.loadLabel(pm).toString() }
                        .filter { it.first != packageName }
                        .distinctBy { it.first }
                        .sortedBy { it.second.lowercase() }
                        .map { mapOf("package" to it.first, "label" to it.second) }
                } catch (e: Exception) {
                    emptyList()
                }
                ui.post { result.success(out) }
            }
            "appIcon" -> {
                val pkg = call.arguments as? String
                worker.execute {
                    val bytes: ByteArray? = try {
                        if (pkg == null) null else toPng(packageManager.getApplicationIcon(pkg), 72)
                    } catch (e: Exception) {
                        null
                    }
                    ui.post { result.success(bytes) }
                }
            }
            "openVpnSettings" -> result.success(launch(Intent(Settings.ACTION_VPN_SETTINGS)))
            "isIgnoringBattery" -> {
                val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
                result.success(pm.isIgnoringBatteryOptimizations(packageName))
            }
            "openBatterySettings" -> {
                val direct = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS)
                    .setData(Uri.parse("package:$packageName"))
                val ok = launch(direct) || launch(Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))
                result.success(ok)
            }
            "requestNotifications" -> {
                if (Build.VERSION.SDK_INT >= 33 &&
                    checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED
                ) {
                    requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS), 7001)
                    result.success(false)
                } else {
                    result.success(true)
                }
            }
            else -> result.notImplemented()
        }
    }

    private fun launch(i: Intent): Boolean = try {
        i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        startActivity(i)
        true
    } catch (e: Exception) {
        false
    }

    private fun toPng(d: Drawable, size: Int): ByteArray {
        val bmp = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bmp)
        d.setBounds(0, 0, size, size)
        d.draw(canvas)
        val out = ByteArrayOutputStream()
        bmp.compress(Bitmap.CompressFormat.PNG, 100, out)
        bmp.recycle()
        return out.toByteArray()
    }
}
'''


def patch_kotlin():
    for pat in ("kotlin", "java"):
        for f in glob.glob(os.path.join(MAIN, pat, "**", "MainActivity.*"), recursive=True):
            os.remove(f)
    write(os.path.join(MAIN, "kotlin", *APP_ID.split("."), "MainActivity.kt"), KOTLIN)


# --------------------------------------------------------------- resources
SHIELD = "M12,1L3,5v6c0,5.55 3.84,10.74 9,12 5.16,-1.26 9,-6.45 9,-12L21,5l-9,-4z"
CROSS = (
    "M9.2,8.2L12,11L14.8,8.2L15.8,9.2L13,12L15.8,14.8L14.8,15.8L12,13"
    "L9.2,15.8L8.2,14.8L11,12L8.2,9.2Z"
)


def vector(color, extra=""):
    return (
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<vector xmlns:android="http://schemas.android.com/apk/res/android"\n'
        '    android:width="24dp" android:height="24dp"\n'
        '    android:viewportWidth="24" android:viewportHeight="24">\n'
        '    <path android:fillColor="%s" android:fillType="evenOdd"\n'
        '        android:pathData="%s %s"/>\n'
        "</vector>\n" % (color, SHIELD, CROSS)
    )


def patch_resources():
    res = os.path.join(MAIN, "res")
    # Monochrome status-bar icon (looked up by the VPN plugin as mipmap/ic_stat_vpn).
    write(os.path.join(res, "mipmap-anydpi-v24", "ic_stat_vpn.xml"), vector("#FFFFFFFF"))
    # Launcher icon (adaptive, API 26+; older devices keep Flutter's default PNG).
    write(os.path.join(res, "drawable", "ic_shield.xml"), vector("#FF2F7EFF"))
    write(
        os.path.join(res, "drawable", "ic_launcher_foreground.xml"),
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<inset xmlns:android="http://schemas.android.com/apk/res/android"\n'
        '    android:drawable="@drawable/ic_shield" android:inset="22%"/>\n',
    )
    write(
        os.path.join(res, "values", "ic_launcher_colors.xml"),
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<resources><color name="ic_launcher_background">#FF0A0D14</color></resources>\n',
    )
    write(
        os.path.join(res, "mipmap-anydpi-v26", "ic_launcher.xml"),
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '    <background android:drawable="@color/ic_launcher_background"/>\n'
        '    <foreground android:drawable="@drawable/ic_launcher_foreground"/>\n'
        "</adaptive-icon>\n",
    )
    # Keep dynamically-looked-up resources through R8 resource shrinking.
    write(
        os.path.join(res, "raw", "keep.xml"),
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<resources xmlns:tools="http://schemas.android.com/tools"\n'
        '    tools:keep="@mipmap/ic_stat_vpn,@mipmap/ic_launcher,@drawable/ic_shield" />\n',
    )


def main():
    if not os.path.isdir(APP):
        die("android/app not found - run flutter create first")
    patch_manifest()
    patch_gradle()
    patch_kotlin()
    patch_resources()
    print("Patched Android project for %s (%s)" % (APP_LABEL, APP_ID))


if __name__ == "__main__":
    main()
